 38	package br.pousada.marealta.api;
 39	
 40	import io.javalin.Javalin;
 41	import br.pousada.marealta.model.*;
 42	import br.pousada.marealta.database.Database;
 43	import br.pousada.marealta.database.RoomRepository;
 44	import br.pousada.marealta.database.ReservationRepository;
 45	import br.pousada.marealta.service.PricingService;
 46	import br.pousada.marealta.service.MessageService;
 47	import br.pousada.marealta.service.DocumentFormatter;
 48	import org.slf4j.Logger;
 49	import org.slf4j.LoggerFactory;
 50	import java.sql.Connection;
 51	import java.time.LocalDate;
 52	import java.time.format.DateTimeFormatter;
 53	
 54	public class ReservationHandler {
 55	    private static final Logger logger = LoggerFactory.getLogger(ReservationHandler.class);
 56	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 57	
 58	    public static void register(Javalin app) {
 59	        app.post("/reservations", ctx -> createReservation(ctx));
 60	        app.get("/reservations/{id}", ctx -> getReservation(ctx));
 61	        app.post("/reservations/{id}/confirmation", ctx -> confirmReservation(ctx));
 62	        app.post("/reservations/{id}/cancellation", ctx -> cancelReservation(ctx));
 63	        app.post("/reservations/{id}/check-in", ctx -> checkIn(ctx));
 64	        app.post("/reservations/{id}/check-out", ctx -> checkOut(ctx));
 65	        app.get("/reservations/{id}/document", ctx -> getDocument(ctx));
 66	    }
 67	
 68	    private static void createReservation(io.javalin.http.Context ctx) {
 69	        try (Connection conn = Database.getConnection()) {
 70	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
 71	
 72	            if (req == null || !hasRequiredFields(req)) {
 73	                ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Missing required fields"));
 74	                return;
 75	            }
 76	
 77	            int roomNumber = req.roomNumber;
 78	            String guestName = req.guestName;
 79	            String guestEmail = req.guestEmail;
 80	            String guestCpf = req.guestCpf;
 81	            LocalDate checkIn = LocalDate.parse(req.checkIn, DATE_FORMAT);
 82	            LocalDate checkOut = LocalDate.parse(req.checkOut, DATE_FORMAT);
 83	            int guests = req.guests;
 84	            RatePlan ratePlan = RatePlan.valueOf(req.ratePlan);
 85	
 86	            if (!checkOut.isAfter(checkIn)) {
 87	                ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Check-out must be after check-in"));
 88	                return;
 89	            }
 90	
 91	            if (guests < 1) {
 92	                ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "At least one guest is required"));
 93	                return;
 94	            }
 95	
 96	            var roomOpt = RoomRepository.findByNumber(roomNumber);
 97	            if (roomOpt.isEmpty()) {
 98	                ctx.status(404).json(ErrorResponse.error("ROOM_NOT_FOUND", "Room not found"));
 99	                return;
100	            }
101	
102	            Room room = roomOpt.get();
103	            if (guests > room.getCapacity()) {
104	                ctx.status(422).json(ErrorResponse.error("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
105	                return;
106	            }
107	
108	            if (!ReservationRepository.isRoomAvailable(conn, roomNumber, checkIn, checkOut)) {
109	                ctx.status(409).json(ErrorResponse.error("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
110	                return;
111	            }
112	
113	            int nights = PricingService.calculateNights(checkIn, checkOut);
114	            double subtotal = 0;
115	            for (int i = 0; i < nights; i++) {
116	                LocalDate date = checkIn.plusDays(i);
117	                double nightlyRate = PricingService.calculateNightlyRateForDate(room.getNightlyRate(), date);
118	                subtotal += nightlyRate;
119	            }
120	            subtotal = PricingService.round(subtotal);
121	
122	            double discount = PricingService.calculateDiscount(subtotal, ratePlan.toString());
123	            double total = PricingService.calculateTotal(subtotal, discount);
124	
125	            Reservation reservation = new Reservation(
126	                0,
127	                roomNumber,
128	                guestName,
129	                guestEmail,
130	                guestCpf,
131	                checkIn,
132	                checkOut,
133	                guests,
134	                ratePlan,
135	                nights,
136	                subtotal,
137	                discount,
138	                total,
139	                ReservationStatus.PENDING,
140	                0,
141	                null
142	            );
143	
144	            Reservation saved = ReservationRepository.insert(conn, reservation);
145	            ctx.status(201).json(saved);
146	
147	        } catch (IllegalArgumentException e) {
148	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid request format"));
149	        } catch (Exception e) {
150	            logger.error("Error creating reservation", e);
151	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to create reservation"));
152	        }
153	    }
154	
155	    private static void getReservation(io.javalin.http.Context ctx) {
156	        try (Connection conn = Database.getConnection()) {
157	            long id = Long.parseLong(ctx.pathParam("id"));
158	            var reservation = ReservationRepository.findById(conn, id);
159	
160	            if (reservation.isEmpty()) {
161	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Reservation not found"));
162	                return;
163	            }
164	
165	            ctx.json(reservation.get());
166	        } catch (NumberFormatException e) {
167	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid reservation ID"));
168	        } catch (Exception e) {
169	            logger.error("Error getting reservation", e);
170	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to get reservation"));
171	        }
172	    }
173	
174	    private static void confirmReservation(io.javalin.http.Context ctx) {
175	        try (Connection conn = Database.getConnection()) {
176	            long id = Long.parseLong(ctx.pathParam("id"));
177	            var reservationOpt = ReservationRepository.findById(conn, id);
178	
179	            if (reservationOpt.isEmpty()) {
180	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Reservation not found"));
181	                return;
182	            }
183	
184	            Reservation reservation = reservationOpt.get();
185	            if (reservation.getStatus() != ReservationStatus.PENDING) {
186	                ctx.status(409).json(ErrorResponse.error("OPERATION_NOT_ALLOWED", "Can only confirm pending reservations"));
187	                return;
188	            }
189	
190	            reservation.setStatus(ReservationStatus.CONFIRMED);
191	            reservation.setAmountPaid(reservation.getTotal());
192	            ReservationRepository.update(conn, reservation);
193	
194	            var roomOpt = RoomRepository.findByNumber(reservation.getRoomNumber());
195	            Room room = roomOpt.get();
196	
197	            String documentText = DocumentFormatter.format(new Document(
198	                reservation.getId(),
199	                reservation.getGuestName(),
200	                reservation.getGuestCpf(),
201	                reservation.getRoomNumber(),
202	                room.getType(),
203	                reservation.getCheckIn(),
204	                reservation.getCheckOut(),
205	                reservation.getNights(),
206	                reservation.getSubtotal(),
207	                reservation.getDiscount() > 0 ? reservation.getDiscount() : null,
208	                reservation.getTotal()
209	            ));
210	
211	            MessageService.sendConfirmationEmail(conn, reservation.getId(), reservation.getGuestName(), reservation.getGuestEmail(), documentText);
212	
213	            ctx.json(reservation);
214	        } catch (NumberFormatException e) {
215	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid reservation ID"));
216	        } catch (Exception e) {
217	            logger.error("Error confirming reservation", e);
218	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to confirm reservation"));
219	        }
220	    }
221	
222	    private static void cancelReservation(io.javalin.http.Context ctx) {
223	        try (Connection conn = Database.getConnection()) {
224	            long id = Long.parseLong(ctx.pathParam("id"));
225	            var reservationOpt = ReservationRepository.findById(conn, id);
226	
227	            if (reservationOpt.isEmpty()) {
228	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Reservation not found"));
229	                return;
230	            }
231	
232	            Reservation reservation = reservationOpt.get();
233	            if (reservation.getStatus() != ReservationStatus.PENDING && reservation.getStatus() != ReservationStatus.CONFIRMED) {
234	                ctx.status(409).json(ErrorResponse.error("OPERATION_NOT_ALLOWED", "Can only cancel pending or confirmed reservations"));
235	                return;
236	            }
237	
238	            double refund = 0;
239	            if (reservation.getStatus() == ReservationStatus.CONFIRMED && reservation.getRatePlan() == RatePlan.STANDARD) {
240	                refund = reservation.getAmountPaid();
241	            }
242	
243	            reservation.setStatus(ReservationStatus.CANCELLED);
244	            reservation.setRefund(refund);
245	            ReservationRepository.update(conn, reservation);
246	
247	            ctx.json(reservation);
248	        } catch (NumberFormatException e) {
249	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid reservation ID"));
250	        } catch (Exception e) {
251	            logger.error("Error cancelling reservation", e);
252	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to cancel reservation"));
253	        }
254	    }
255	
256	    private static void checkIn(io.javalin.http.Context ctx) {
257	        try (Connection conn = Database.getConnection()) {
258	            long id = Long.parseLong(ctx.pathParam("id"));
259	            var reservationOpt = ReservationRepository.findById(conn, id);
260	
261	            if (reservationOpt.isEmpty()) {
262	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Reservation not found"));
263	                return;
264	            }
265	
266	            Reservation reservation = reservationOpt.get();
267	            if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
268	                ctx.status(409).json(ErrorResponse.error("OPERATION_NOT_ALLOWED", "Can only check in confirmed reservations"));
269	                return;
270	            }
271	
272	            reservation.setStatus(ReservationStatus.CHECKED_IN);
273	            ReservationRepository.update(conn, reservation);
274	
275	            ctx.json(reservation);
276	        } catch (NumberFormatException e) {
277	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid reservation ID"));
278	        } catch (Exception e) {
279	            logger.error("Error checking in reservation", e);
280	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to check in"));
281	        }
282	    }
283	
284	    private static void checkOut(io.javalin.http.Context ctx) {
285	        try (Connection conn = Database.getConnection()) {
286	            long id = Long.parseLong(ctx.pathParam("id"));
287	            var reservationOpt = ReservationRepository.findById(conn, id);
288	
289	            if (reservationOpt.isEmpty()) {
290	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Reservation not found"));
291	                return;
292	            }
293	
294	            Reservation reservation = reservationOpt.get();
295	            if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
296	                ctx.status(409).json(ErrorResponse.error("OPERATION_NOT_ALLOWED", "Can only check out reservations that are checked in"));
297	                return;
298	            }
299	
300	            reservation.setStatus(ReservationStatus.CHECKED_OUT);
301	            ReservationRepository.update(conn, reservation);
302	
303	            var roomOpt = RoomRepository.findByNumber(reservation.getRoomNumber());
304	            Room room = roomOpt.get();
305	
306	            Document doc = new Document(
307	                reservation.getId(),
308	                reservation.getGuestName(),
309	                reservation.getGuestCpf(),
310	                reservation.getRoomNumber(),
311	                room.getType(),
312	                reservation.getCheckIn(),
313	                reservation.getCheckOut(),
314	                reservation.getNights(),
315	                reservation.getSubtotal(),
316	                reservation.getDiscount() > 0 ? reservation.getDiscount() : null,
317	                reservation.getTotal()
318	            );
319	
320	            ctx.json(doc);
321	        } catch (NumberFormatException e) {
322	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid reservation ID"));
323	        } catch (Exception e) {
324	            logger.error("Error checking out reservation", e);
325	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to check out"));
326	        }
327	    }
328	
329	    private static void getDocument(io.javalin.http.Context ctx) {
330	        try (Connection conn = Database.getConnection()) {
331	            long id = Long.parseLong(ctx.pathParam("id"));
332	            var reservationOpt = ReservationRepository.findById(conn, id);
333	
334	            if (reservationOpt.isEmpty()) {
335	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Reservation not found"));
336	                return;
337	            }
338	
339	            Reservation reservation = reservationOpt.get();
340	            if (reservation.getStatus() == ReservationStatus.PENDING || reservation.getStatus() == ReservationStatus.CANCELLED) {
341	                ctx.status(404).json(ErrorResponse.error("RESERVATION_NOT_FOUND", "Document only available for confirmed reservations"));
342	                return;
343	            }
344	
345	            var roomOpt = RoomRepository.findByNumber(reservation.getRoomNumber());
346	            Room room = roomOpt.get();
347	
348	            Document doc = new Document(
349	                reservation.getId(),
350	                reservation.getGuestName(),
351	                reservation.getGuestCpf(),
352	                reservation.getRoomNumber(),
353	                room.getType(),
354	                reservation.getCheckIn(),
355	                reservation.getCheckOut(),
356	                reservation.getNights(),
357	                reservation.getSubtotal(),
358	                reservation.getDiscount() > 0 ? reservation.getDiscount() : null,
359	                reservation.getTotal()
360	            );
361	
362	            ctx.json(doc);
363	        } catch (NumberFormatException e) {
364	            ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Invalid reservation ID"));
365	        } catch (Exception e) {
366	            logger.error("Error getting document", e);
367	            ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to get document"));
368	        }
369	    }
370	
371	    private static boolean hasRequiredFields(CreateReservationRequest req) {
372	        return req.roomNumber > 0 && req.guestName != null && req.guestEmail != null &&
373	               req.guestCpf != null && req.checkIn != null && req.checkOut != null &&
374	               req.guests > 0 && req.ratePlan != null;
375	    }
376	}

