     7	public class DocumentFormatter {
     8	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
     9	
    10	    public static String format(Document doc) {
    11	        StringBuilder sb = new StringBuilder();
    12	
    13	        sb.append(String.format("Comprovante de reserva nº %d\n", doc.getReservationId()));
    14	        sb.append(String.format("Hóspede: %s (CPF %s)\n", doc.getGuestName(), formatCpf(doc.getGuestCpf())));
    15	        sb.append(String.format("Quarto: %d (%s)\n", doc.getRoomNumber(), doc.getRoomType()));
    16	
    17	        String nights = doc.getNights() == 1 ? "1 diária" : doc.getNights() + " diárias";
    18	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
    19	            formatDate(doc.getCheckIn()),
    20	            formatDate(doc.getCheckOut()),
    21	            nights));
    22	
    23	        sb.append(String.format("Diárias: %s\n", formatMoney(doc.getSubtotal())));
    24	
    25	        if (doc.getDiscount() != null && doc.getDiscount() > 0) {
    26	            sb.append(String.format("Desconto: %s\n", formatMoney(doc.getDiscount())));
    27	        }
    28	
    29	        sb.append(String.format("Total: %s", formatMoney(doc.getTotal())));
    30	
    31	        return sb.toString();
    32	    }
    33	
    34	    private static String formatDate(LocalDate date) {
    35	        return date.format(DATE_FORMAT);
    36	    }
    37	
    38	    private static String formatMoney(double value) {
    39	        String formatted = String.format("%.2f", value);
    40	        String[] parts = formatted.split("\\.");
    41	        String intPart = parts[0];
    42	        String decPart = parts[1];
    43	
    44	        StringBuilder result = new StringBuilder();
    45	        int len = intPart.length();
    46	        for (int i = 0; i < len; i++) {
    47	            if (i > 0 && (len - i) % 3 == 0) {
    48	                result.append(".");
    49	            }
    50	            result.append(intPart.charAt(i));
    51	        }
    52	        return "R$ " + result + "," + decPart;
    53	    }
    54	
    55	    private static String formatCpf(String cpf) {
    56	        if (cpf.length() == 11) {
    57	            return String.format("%s.%s.%s-%s",
    58	                cpf.substring(0, 3),
    59	                cpf.substring(3, 6),
    60	                cpf.substring(6, 9),
    61	                cpf.substring(9));
    62	        }
    63	        return cpf;
    64	    }
    65	}
