     6	
     7	public class PricingService {
     8	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
     9	    private static final double NON_REFUNDABLE_DISCOUNT = 0.15;
    10	
    11	    public static boolean isHighSeason(LocalDate date) {
    12	        int month = date.getMonthValue();
    13	        int day = date.getDayOfMonth();
    14	
    15	        if (month == 7) return true;
    16	
    17	        if (month == 12 && day >= 15) return true;
    18	
    19	        if (month == 1 || month == 2) return true;
    20	
    21	        return false;
    22	    }
    23	
    24	    public static double calculateNightlyRate(double baseRate) {
    25	        return round(baseRate);
    26	    }
    27	
    28	    public static double calculateNightlyRateForDate(double baseRate, LocalDate date) {
    29	        if (isHighSeason(date)) {
    30	            return round(baseRate * HIGH_SEASON_MULTIPLIER);
    31	        }
    32	        return round(baseRate);
    33	    }
    34	
    35	    public static double calculateSubtotal(double nightlyRate, int nights) {
    36	        return round(nightlyRate * nights);
    37	    }
    38	
    39	    public static double calculateDiscount(double subtotal, String ratePlan) {
    40	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    41	            return round(subtotal * NON_REFUNDABLE_DISCOUNT);
    42	        }
    43	        return 0;
    44	    }
    45	
    46	    public static double calculateTotal(double subtotal, double discount) {
    47	        return round(subtotal - discount);
    48	    }
    49	
    50	    public static double round(double value) {
    51	        return new BigDecimal(value)
    52	            .setScale(2, RoundingMode.HALF_EVEN)
    53	            .doubleValue();
    54	    }
    55	
    56	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    57	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    58	    }
    59	}

