    18	public class ReportHandler {
    19	    private static final Logger logger = LoggerFactory.getLogger(ReportHandler.class);
    20	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    21	
    22	    public static void register(Javalin app) {
    23	        app.get("/reports/occupancy", ctx -> {
    24	            try {
    25	                String dateStr = ctx.queryParam("date");
    26	                if (dateStr == null) {
    27	                    ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Missing date parameter"));
    28	                    return;
    29	                }
    30	
    31	                LocalDate date = LocalDate.parse(dateStr, DATE_FORMAT);
    32	                String csv = generateOccupancyReport(date);
    33	                ctx.contentType("text/csv;charset=utf-8").result(csv);
    34	            } catch (Exception e) {
    35	                logger.error("Error generating occupancy report", e);
    36	                ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to generate report"));
    37	            }
    38	        });
    39	
    40	        app.get("/reports/revenue", ctx -> {
    41	            try {
    42	                String monthStr = ctx.queryParam("month");
    43	                if (monthStr == null) {
    44	                    ctx.status(400).json(ErrorResponse.error("INVALID_REQUEST", "Missing month parameter"));
    45	                    return;
    46	                }
    47	
    48	                String csv = generateRevenueReport(monthStr);
    49	                ctx.contentType("text/csv;charset=utf-8").result(csv);
    50	            } catch (Exception e) {
    51	                logger.error("Error generating revenue report", e);
    52	                ctx.status(500).json(ErrorResponse.error("INTERNAL_ERROR", "Failed to generate report"));
    53	            }
    54	        });
