    57	    private static String generateOccupancyReport(LocalDate date) throws Exception {
    58	        try (Connection conn = Database.getConnection()) {
    59	            List<Reservation> reservations = ReservationRepository.findByDate(conn, date);
    60	            List<Room> rooms = RoomRepository.findAll();
    61	
    62	            StringBuilder csv = new StringBuilder();
    63	            csv.append("room,type,reservation,check_in,check_out\n");
    64	
    65	            Map<Integer, Reservation> resMap = reservations.stream()
    66	                .collect(Collectors.toMap(Reservation::getRoomNumber, r -> r));
    67	
    68	            for (Room room : rooms) {
    69	                if (resMap.containsKey(room.getNumber())) {
    70	                    Reservation res = resMap.get(room.getNumber());
    71	                    csv.append(String.format("%d,%s,%d,%s,%s\n",
    72	                        room.getNumber(),
    73	                        room.getType(),
    74	                        res.getId(),
    75	                        res.getCheckIn().format(DATE_FORMAT),
    76	                        res.getCheckOut().format(DATE_FORMAT)));
    77	                }
    78	            }
    79	
    80	            csv.append(String.format("total,%d/%d\n", reservations.size(), rooms.size()));
    81	
    82	            return csv.toString();
    83	        }
    84	    }
    85	
    86	    private static String generateRevenueReport(String month) throws Exception {
    87	        try (Connection conn = Database.getConnection()) {
    88	            List<Reservation> reservations = ReservationRepository.findByMonth(conn, month);
    89	
    90	            StringBuilder csv = new StringBuilder();
    91	            csv.append("reservation,room,check_in,check_out,status,amount\n");
    92	
    93	            double total = 0;
    94	            for (Reservation res : reservations) {
    95	                double amount = res.getAmountPaid();
    96	                if (res.getRefund() != null) {
    97	                    amount -= res.getRefund();
    98	                }
    99	
   100	                csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
   101	                    res.getId(),
   102	                    res.getRoomNumber(),
   103	                    res.getCheckIn().format(DATE_FORMAT),
   104	                    res.getCheckOut().format(DATE_FORMAT),
   105	                    res.getStatus(),
   106	                    amount));
   107	
   108	                total += amount;
   109	            }
   110	
   111	            csv.append(String.format("total,%.2f\n", total));
   112	
   113	            return csv.toString();
   114	        }
   115	    }
   116	}
